er\",\"settings\":{\"_css_classes\":\"fisica-site-header\",\"flex_direction\":\"row\",\"content_width\":\"boxed\",\"boxed_width\":{\"unit\":\"px\",\"size\":1284,\"sizes\":[]},\"min_height\":{\"unit\":\"px\",\"size\":94,\"sizes\":[]},\"flex_justify_content\":\"space-between\",\"flex_align_items\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"12\",\"right\":\"20\",\"bottom\":\"12\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"fisheaderlogo2\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":26},\"width_mobile\":{\"unit\":\"%\",\"size\":52,\"sizes\":[]}},\"elements\":[{\"id\":\"fislogoimg2\",\"elType\":\"widget\",\"widgetType\":\"image\",\"settings\":{\"image\":{\"url\":\"http://localhost/fisica/wp-content/uploads/2025/07/Imagem_do_WhatsApp_de_2025-07-14_a_s__23.42.06_25299ca5-removebg-preview.png\",\"id\":47,\"size\":\"\",\"alt\":\"Instituto de Física UERJ\",\"source\":\"library\"},\"align\":\"left\",\"width\":{\"unit\":\"%\",\"size\":74,\"sizes\":[]},\"width_mobile\":{\"unit\":\"%\",\"size\":96,\"sizes\":[]},\"link_to\":\"custom\",\"link\":{\"url\":\"http://localhost/fisica/\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},\"elements\":[]}],\"isInner\":true},{\"id\":\"fisheadermenu2\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"width\":{\"unit\":\"%\",\"size\":74},\"width_mobile\":{\"unit\":\"%\",\"size\":48,\"sizes\":[]}},\"elements\":[{\"id\":\"fismenunav2\",\"elType\":\"widget\",\"widgetType\":\"navigation-menu\",\"settings\":{\"menu\":\"menu\",\"navmenu_align\":\"right\",\"resp_align\":\"right\",\"padding_vertical_menu_item\":{\"unit\":\"px\",\"size\":12,\"sizes\":[]},\"padding_horizontal_menu_item\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"color_menu_item\":\"#F4F8FC\",\"toggle_color\":\"#FFFFFF\",\"menu_typography_typography\":\"custom\",\"menu_typography_font_family\":\"Montserrat\",\"menu_typography_font_siz