    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"background_background\":\"gradient\",\"background_color_b\":\"\",\"__globals__\":{\"background_color\":\"\"},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_flex_align_self\":\"center\"},\"elements\":[{\"id\":\"effc71e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Eventos\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_font_weight\":\"bold\",\"text_shadow_text_shadow\":{\"horizontal\":7,\"vertical\":11,\"blur\":11,\"color\":\"rgba(0,0,0,0.3)\"},\"__globals__\":{\"typography_typography\":\"\",\"title_color\":\"\"},\"title_color\":\"#003BB1\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"e0a170a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":40,\"column\":\"40\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"e2597eb\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"23cb185\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsAp