tivePanel = app.querySelector(\'.fisica-docentes-panel.is-active\');\\n        if (!activePanel) {\\n          return;\\n        }\\n\\n        const term = (search?.value || \'\').trim().toLowerCase();\\n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));\\n        let visible = 0;\\n\\n        rows.forEach((row) => {\\n          const haystack = row.dataset.search || \'\';\\n          const match = term === \'\' || haystack.includes(term);\\n          row.hidden = !match;\\n          if (match) {\\n            visible += 1;\\n          }\\n        });\\n\\n        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');\\n        if (empty) {\\n          empty.hidden = visible !== 0;\\n        }\\n\\n        if (feedback) {\\n          if (term === \'\') {\\n            feedback.textContent = \'Consulte a rela\\u00e7\\u00e3o completa de docentes por \\u00e1rea.\';\\n          } else {\\n            feedback.textContent = visible + \' docente(s) encontrado(s) na \\u00e1rea selecionada.\';\\n          }\\n        }\\n      };\\n\\n      tabs.forEach((tab) => {\\n        tab.addEventListener(\'click\', () => activate(Number(tab.dataset.docentesTab || 0)));\\n      });\\n\\n      search?.addEventListener(\'input\', filterRows);\\n      activate(0);\\n    })();\\n  <\\/script>\\n<\\/section>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),(6776,1134,'_elementor_edit_mode','builder'),(6777,1134,'_elementor_template_type','wp-page'),(6778,1134,'_elementor_version','3.32.1'),(6779,1134,'_wp_page_template','elementor_header_footer'),(6780,1134,'_elementor_data','[{\"id\":\"fisicadocenteshtmlv2\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"fisicadocenteshtmlwidgetv2\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section