 = app.querySelector(\'.fisica-docentes-panel.is-active\');\\n        if (!activePanel) {\\n          return;\\n        }\\n\\n        const term = (search?.value || \'\').trim().toLowerCase();\\n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));\\n        let visible = 0;\\n\\n        rows.forEach((row) => {\\n          const haystack = row.dataset.search || \'\';\\n          const match = term === \'\' || haystack.includes(term);\\n          row.hidden = !match;\\n          if (match) {\\n            visible += 1;\\n          }\\n        });\\n\\n        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');\\n        if (empty) {\\n          empty.hidden = visible !== 0;\\n        }\\n\\n        if (feedback) {\\n          if (term === \'\') {\\n            feedback.textContent = \'Consulte a rela\\u00e7\\u00e3o completa de docentes por \\u00e1rea.\';\\n          } else {\\n            feedback.textContent = visible + \' docente(s) encontrado(s) na \\u00e1rea selecionada.\';\\n          }\\n        }\\n      };\\n\\n      tabs.forEach((tab) => {\\n        tab.addEventListener(\'click\', () => activate(Number(tab.dataset.docentesTab || 0)));\\n      });\\n\\n      search?.addEventListener(\'input\', filterRows);\\n      activate(0);\\n    })();\\n  <\\/script>\\n<\\/section>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),(7290,1187,'_wp_attached_file','2026/05/Projetos_EXT_FIS_Site_do_IF.xlsx'),(7291,1187,'_wp_attachment_metadata','a:1:{s:8:\"filesize\";i:25208;}'),(7292,1188,'_wp_page_template','elementor_header_footer'),(7293,1188,'_elementor_edit_mode','builder'),(7294,1188,'_elementor_template_type','wp-page'),(7295,1188,'_elementor_version','3.32.1'),(7307,1091,'_wp_old_date','2026-05-06'),(7308,1190,'_elementor_edit_mode','builder'),(7309,1190,'_elementor_template_type','wp-page'),(7310,1190,'_elementor_version','3.32.1'),(7311,1190,'_wp_page_template','default'),(7312,1190,'_elementor_d